//! Arbitrary-precision decimal arithmetic.
//!
//! A `Decimal` is stored as a sign flag, a magnitude (an integer represented as
//! little-endian base-1e9 chunks) and a scale (the number of fractional digits).
//! The represented value is `(-1)^neg * mag / 10^scale`.

use std::cmp::Ordering;
use std::ops::{Add, Mul, Sub};

const BASE: u64 = 1_000_000_000;

/// Type implementing arbitrary-precision decimal arithmetic
#[derive(Clone, Debug)]
pub struct Decimal {
    neg: bool,
    /// Magnitude in little-endian base 1_000_000_000 chunks (no leading zeros).
    mag: Vec<u32>,
    /// Number of decimal digits the magnitude is scaled by (value = mag / 10^scale).
    scale: u32,
}

/// Trim leading zero chunks from the most significant end.
fn trim(m: &mut Vec<u32>) {
    while m.last() == Some(&0) {
        m.pop();
    }
}

/// Canonical constructor: normalizes zero (empty magnitude => zero).
fn make(neg: bool, mut mag: Vec<u32>, scale: u32) -> Decimal {
    trim(&mut mag);
    if mag.is_empty() {
        Decimal { neg: false, mag: Vec::new(), scale: 0 }
    } else {
        Decimal { neg, mag, scale }
    }
}

/// Compare two magnitudes (as integers) ignoring scale.
fn cmp_mag(a: &[u32], b: &[u32]) -> Ordering {
    match a.len().cmp(&b.len()) {
        Ordering::Equal => a.iter().rev().zip(b.iter().rev()).find_map(|(x, y)| x.cmp(y).then(())),
        other => other,
    }
}

/// Add two magnitudes.
fn add_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut out = Vec::with_capacity(a.len().max(b.len()) + 1);
    let mut carry: u64 = 0;
    for i in 0..a.len().max(b.len()) {
        let x = *a.get(i).unwrap_or(&0) as u64;
        let y = *b.get(i).unwrap_or(&0) as u64;
        let v = x + y + carry;
        out.push((v % BASE) as u32);
        carry = v / BASE;
    }
    if carry > 0 {
        out.push(carry as u32);
    }
    out
}

/// Subtract two magnitudes, assuming `a >= b`.
fn sub_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
    let mut out = Vec::with_capacity(a.len());
    let mut borrow: i64 = 0;
    for i in 0..a.len() {
        let x = *a.get(i).unwrap_or(&0) as i64;
        let y = *b.get(i).unwrap_or(&0) as i64;
        let mut v = x - y - borrow;
        if v < 0 {
            v += BASE as i64;
            borrow = 1;
        } else {
            borrow = 0;
        }
        out.push(v as u32);
    }
    out
}

/// Multiply two magnitudes (schoolbook multiplication).
fn mul_mag(a: &[u32], b: &[u32]) -> Vec<u32> {
    if a.is_empty() || b.is_empty() {
        return Vec::new();
    }
    let mut res = vec![0u32; a.len() + b.len()];
    for (i, ai) in a.iter().enumerate() {
        let a = *ai as u64;
        let mut carry: u64 = 0;
        for (j, bj) in b.iter().enumerate() {
            let v = res[i + j] as u64 + a * (*bj as u64) + carry;
            res[i + j] = (v % BASE) as u32;
            carry = v / BASE;
        }
        let mut k = i + b.len();
        while carry > 0 {
            let v = res[k] as u64 + carry;
            res[k] = (v % BASE) as u32;
            carry = v / BASE;
            k += 1;
        }
    }
    trim(&mut res);
    res
}

/// Multiply a magnitude by 10^k (k fractional-shift amount).
fn rescale(m: &[u32], k: u32) -> Vec<u32> {
    if k == 0 || m.is_empty() {
        return m.to_vec();
    }
    let q = (k / 9) as usize; // whole base-1e9 chunks
    let r = (k % 9) as usize; // remaining decimal digits
    let mul = POW10[r] as u64;
    let mut out = Vec::with_capacity(m.len() + q + 1);
    let mut carry: u64 = 0;
    for &c in m {
        let v = c as u64 * mul + carry;
        out.push((v % BASE) as u32);
        carry = v / BASE;
    }
    while carry > 0 {
        out.push((carry % BASE as u64) as u32);
        carry /= BASE;
    }
    // Shift left by q chunks (least significant side).
    let mut shifted = vec![0u32; q];
    shifted.extend_from_slice(&out);
    trim(&mut shifted);
    shifted
}

const POW10: [u32; 9] = [1, 10, 100, 1_000, 10_000, 100_000, 1_000_000, 10_000_000, 100_000_000];

/// Total ordering comparison between two decimals.
fn cmp_val(a: &Decimal, b: &Decimal) -> Ordering {
    if a.neg != b.neg {
        // Zero is never stored with the negative flag, so this is unambiguous.
        return if a.neg { Ordering::Less } else { Ordering::Greater };
    }
    let d = a.scale.max(b.scale);
    let ma = rescale(&a.mag, d - a.scale);
    let mb = rescale(&b.mag, d - b.scale);
    let r = cmp_mag(&ma, &mb);
    if a.neg {
        r.reverse()
    } else {
        r
    }
}

/// Signed addition of two (sign, magnitude, scale) triples.
fn add_raw(neg_a: bool, ma: &[u32], sa: u32, neg_b: bool, mb: &[u32], sb: u32) -> Decimal {
    let d = sa.max(sb);
    let ma = rescale(ma, d - sa);
    let mb = rescale(mb, d - sb);
    if neg_a == neg_b {
        make(neg_a, add_mag(&ma, &mb), d)
    } else {
        match cmp_mag(&ma, &mb) {
            Ordering::Equal => make(false, Vec::new(), 0),
            Ordering::Greater => make(neg_a, sub_mag(&ma, &mb), d),
            Ordering::Less => make(neg_b, sub_mag(&mb, &ma), d),
        }
    }
}

fn parse_mag(int_digits: &[u8], frac_digits: &[u8]) -> Vec<u32> {
    // Concatenate integer and fractional digits; the resulting digit string is
    // the base-10 representation of the magnitude.
    let digits: Vec<u8> = int_digits
        .iter()
        .chain(frac_digits.iter())
        .map(|&b| b - b'0')
        .collect();
    let mut mag = Vec::new();
    let mut end = digits.len();
    while end > 0 {
        let start = end.saturating_sub(9);
        let mut chunk: u32 = 0;
        let mut mult: u32 = 1;
        for &d in digits[start..end].iter().rev() {
            chunk += d as u32 * mult;
            mult *= 10;
        }
        mag.push(chunk);
        end = start;
    }
    trim(&mut mag);
    mag
}

impl Decimal {
    pub fn try_from(input: &str) -> Option<Decimal> {
        let s = input.trim();
        let (neg, rest) = match s.strip_prefix('-') {
            Some(r) => (true, r),
            None => (false, s.strip_prefix('+').unwrap_or(s)),
        };
        let mut parts = rest.split('.');
        let ip = parts.next().unwrap_or("");
        let fp = parts.next().unwrap_or("");
        if parts.next().is_some() {
            return None; // more than one decimal point
        }
        if (!ip.bytes().all(|b| b.is_ascii_digit()) || !fp.bytes().all(|b| b.is_ascii_digit()))
            || (ip.is_empty() && fp.is_empty())
        {
            return None;
        }
        let mag = parse_mag(ip.as_bytes(), fp.as_bytes());
        Some(make(neg, mag, fp.len() as u32))
    }
}

impl PartialEq for Decimal {
    fn eq(&self, other: &Self) -> bool {
        cmp_val(self, other) == Ordering::Equal
    }
}

impl Eq for Decimal {}

impl Ord for Decimal {
    fn cmp(&self, other: &Self) -> Ordering {
        cmp_val(self, other)
    }
}

impl PartialOrd for Decimal {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Add for Decimal {
    type Output = Decimal;
    fn add(self, rhs: Decimal) -> Decimal {
        add_raw(self.neg, &self.mag, self.scale, rhs.neg, &rhs.mag, rhs.scale)
    }
}

impl Sub for Decimal {
    type Output = Decimal;
    fn sub(self, rhs: Decimal) -> Decimal {
        add_raw(self.neg, &self.mag, self.scale, !rhs.neg, &rhs.mag, rhs.scale)
    }
}

impl Mul for Decimal {
    type Output = Decimal;
    fn mul(self, rhs: Decimal) -> Decimal {
        let neg = self.neg != rhs.neg;
        make(neg, mul_mag(&self.mag, &rhs.mag), self.scale + rhs.scale)
    }
}
